code2='''from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = defaultdict(set)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != background:
                points[value].add((r, c))

    groups = []
    for color, cells in points.items():
        seen = set()
        for start in cells:
            if start in seen:
                continue
            seen.add(start)
            stack = [start]
            group = set()
            while stack:
                r, c = stack.pop()
                group.add((r, c))
                for dr in range(-2, 3):
                    for dc in range(-2, 3):
                        if abs(dr) + abs(dc) > 2:
                            continue
                        neighbor = (r + dr, c + dc)
                        if neighbor in cells and neighbor not in seen:
                            seen.add(neighbor)
                            stack.append(neighbor)
            groups.append((color, group))

    candidates = []
    for color, source in groups:
        sr = min(r for r, c in source)
        sc = min(c for r, c in source)
        for other_color, target in groups:
            if other_color != color or len(source) <= len(target):
                continue
            dr = min(r for r, c in target) - sr
            dc = min(c for r, c in target) - sc
            translated = {(r + dr, c + dc) for r, c in source}
            if not target <= translated:
                continue
            missing = {
                (r, c) for r, c in translated - target
                if 0 <= r < h and 0 <= c < w and grid[r][c] == background
            }
            if missing:
                candidates.append((len(target), len(missing), missing))

    result = [row[:] for row in grid]
    if candidates:
        missing = max(candidates, key=lambda item: (item[0], item[1]))[2]
        for r, c in missing:
            result[r][c] = 1
    return result
'''
